∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (self : Breakdown.ScaledMildFramework X κ) (μ t : ℝ),
  0 < μ → 0 ≤ t → self.D μ ∘SL self.G (μ * t) = self.G t ∘SL self.D μ

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {g : ℝ × Breakdown.Space → E} {t : ℝ}
  {x : Breakdown.Space},
  DifferentiableAt ℝ g (t, x) → ∀ (a : Breakdown.Space), (fderiv ℝ (fun y => g (t, y)) x) a = (fderiv ℝ g (t, x)) (0, a)

∀ {k : ℕ} {f : Breakdown.Space → Breakdown.Freq.CSpace}
  (hf : MeasureTheory.MemLp f 1 (Breakdown.SmoothFlow.weightL1Measure k)),
  Breakdown.SmoothFlow.toWeightL1 k f = MeasureTheory.MemLp.toLp f hf

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  {F : Breakdown.ScaledMildFramework X κ} {ρ : X ≃ₗᵢ[ℝ] X},
  F.Commutes ρ → ∀ (μ : ℝ) (x : X), ρ ((F.D μ) x) = (F.D μ) (ρ x)

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (μ : ℝ) (u : ℕ → Breakdown.Piece X (1 - μ)) (n : ℕ),
  Continuous (Breakdown.FracInternal.scaledGluePiece F μ u n)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (w : ℝ → X) (P : ℝ) (k n : ℕ),
  F.stepOp w P k n = 2 • (F.toHeatBilinear.pieceBil (Breakdown.MildFramework.stepLength P k)) (F.profilePiece w P k n)

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (a b τ : ℝ) (x : X),
  0 < a → 0 < b → 0 < τ → (F.D a) (((F.K (b * τ)) ((F.D b⁻¹) x)) ((F.D b⁻¹) x)) = b⁻¹ • (F.D (a * b⁻¹)) (((F.K τ) x) x)

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  {F : Breakdown.ScaledMildFramework X κ} {ρ : X ≃ₗᵢ[ℝ] X} {w : ℝ → X} {P : ℝ},
  F.IsOrbit ρ w P → ∀ (s : ℝ) (n : ℕ), ‖w (s + ↑n * P)‖ = ‖w s‖

∀ {α ν : ℝ} {u₀ : Breakdown.Space → Breakdown.Space} {u : ℝ → Breakdown.Space → Breakdown.Space}
  {p : ℝ → Breakdown.Space → ℝ},
  Breakdown.IsFractionalSolution α ν u₀ u p → ContDiffOn ℝ (↑⊤) (fun z => u z.1 z.2) (Set.Ici 0 ×ˢ Set.univ)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (P : ℝ) (k : ℕ),
  F.stepEnd P k = F.D (Real.exp (-(P / ↑k))) ∘SL Breakdown.pieceEnd (Breakdown.MildFramework.stepLength P k)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (self : Breakdown.ScaledMildFramework X κ) (s τ : ℝ),
  0 ≤ s → 0 < τ → ∀ (u v : X), (self.G s) (((self.K τ) u) v) = ((self.K (s + τ)) u) v

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  {F : Breakdown.ScaledMildFramework X κ} {ρ : X ≃ₗᵢ[ℝ] X} {w : ℝ → X} {P : ℝ},
  F.IsOrbit ρ w P → ∀ (s : ℝ), w (s + P) = ρ (w s)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (self : Breakdown.ScaledMildFramework X κ) (μ τ : ℝ),
  0 < μ → 0 < τ → ∀ (u v : X), μ • (self.D μ) (((self.K (μ * τ)) u) v) = ((self.K τ) ((self.D μ) u)) ((self.D μ) v)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (w : ℝ → X),
  Continuous w → ∀ (s₀ : ℝ), ContinuousOn (F.selfSimilar w s₀) (Set.Ico 0 1)

∀ {X : Type u_1} {inst : NormedAddCommGroup X} {inst_1 : InnerProductSpace ℝ X} {inst_2 : CompleteSpace X} {κ : ℝ}
  {G : ℝ → X →L[ℝ] X} {G_zero : G 0 = ContinuousLinearMap.id ℝ X}
  {G_add : ∀ (s t : ℝ), 0 ≤ s → 0 ≤ t → G (s + t) = G s ∘SL G t} {G_norm : ∀ (t : ℝ), 0 ≤ t → ‖G t‖ ≤ 1}
  {G_cont : ∀ (x : X), ContinuousOn (fun t => (G t) x) (Set.Ici 0)} {K : ℝ → X →L[ℝ] X →L[ℝ] X}
  {K_symm : ∀ (τ : ℝ) (u v : X), ((K τ) u) v = ((K τ) v) u} {CK : ℝ}
  {K_bound : ∀ (τ : ℝ), 0 < τ → τ ≤ 1 → ‖K τ‖ ≤ CK * τ ^ (-(3 / 4))}
  {K_cont : ∀ (u v : X), ContinuousOn (fun τ => ((K τ) u) v) (Set.Ioi 0)}
  {K_shift : ∀ (s τ : ℝ), 0 ≤ s → 0 < τ → ∀ (u v : X), (G s) (((K τ) u) v) = ((K (s + τ)) u) v} {D : ℝ → X →L[ℝ] X}
  {D_norm : ∀ (μ : ℝ), 0 < μ → ∀ (u : X), ‖(D μ) u‖ = μ ^ κ * ‖u‖} {D_one : D 1 = ContinuousLinearMap.id ℝ X}
  {D_mul : ∀ (μ ν : ℝ), 0 < μ → 0 < ν → D (μ * ν) = D μ ∘SL D ν}
  {D_cont : ∀ (u : X), ContinuousOn (fun μ => (D μ) u) (Set.Ioi 0)}
  {D_G : ∀ (μ t : ℝ), 0 < μ → 0 ≤ t → D μ ∘SL G (μ * t) = G t ∘SL D μ}
  {D_K : ∀ (μ τ : ℝ), 0 < μ → 0 < τ → ∀ (u v : X), μ • (D μ) (((K (μ * τ)) u) v) = ((K τ) ((D μ) u)) ((D μ) v)}
  {compact : ∃ S, Dense S ∧ ∀ f ∈ S, ∀ (τ : ℝ), 0 < τ → IsCompactOperator ⇑((K τ) f)} {G_1 : ℝ → X →L[ℝ] X}
  {G_zero_1 : G_1 0 = ContinuousLinearMap.id ℝ X} {G_add_1 : ∀ (s t : ℝ), 0 ≤ s → 0 ≤ t → G_1 (s + t) = G_1 s ∘SL G_1 t}
  {G_norm_1 : ∀ (t : ℝ), 0 ≤ t → ‖G_1 t‖ ≤ 1} {G_cont_1 : ∀ (x : X), ContinuousOn (fun t => (G_1 t) x) (Set.Ici 0)}
  {K_1 : ℝ → X →L[ℝ] X →L[ℝ] X} {K_symm_1 : ∀ (τ : ℝ) (u v : X), ((K_1 τ) u) v = ((K_1 τ) v) u} {CK_1 : ℝ}
  {K_bound_1 : ∀ (τ : ℝ), 0 < τ → τ ≤ 1 → ‖K_1 τ‖ ≤ CK_1 * τ ^ (-(3 / 4))}
  {K_cont_1 : ∀ (u v : X), ContinuousOn (fun τ => ((K_1 τ) u) v) (Set.Ioi 0)}
  {K_shift_1 : ∀ (s τ : ℝ), 0 ≤ s → 0 < τ → ∀ (u v : X), (G_1 s) (((K_1 τ) u) v) = ((K_1 (s + τ)) u) v}
  {D_1 : ℝ → X →L[ℝ] X} {D_norm_1 : ∀ (μ : ℝ), 0 < μ → ∀ (u : X), ‖(D_1 μ) u‖ = μ ^ κ * ‖u‖}
  {D_one_1 : D_1 1 = ContinuousLinearMap.id ℝ X} {D_mul_1 : ∀ (μ ν : ℝ), 0 < μ → 0 < ν → D_1 (μ * ν) = D_1 μ ∘SL D_1 ν}
  {D_cont_1 : ∀ (u : X), ContinuousOn (fun μ => (D_1 μ) u) (Set.Ioi 0)}
  {D_G_1 : ∀ (μ t : ℝ), 0 < μ → 0 ≤ t → D_1 μ ∘SL G_1 (μ * t) = G_1 t ∘SL D_1 μ}
  {D_K_1 :
    ∀ (μ τ : ℝ), 0 < μ → 0 < τ → ∀ (u v : X), μ • (D_1 μ) (((K_1 (μ * τ)) u) v) = ((K_1 τ) ((D_1 μ) u)) ((D_1 μ) v)}
  {compact_1 : ∃ S, Dense S ∧ ∀ f ∈ S, ∀ (τ : ℝ), 0 < τ → IsCompactOperator ⇑⋯},
  { G := G, G_zero := G_zero, G_add := G_add, G_norm := G_norm, G_cont := G_cont, K := K, K_symm := K_symm, CK := CK,
        K_bound := K_bound, K_cont := K_cont, K_shift := K_shift, D := D, D_norm := D_norm, D_one := D_one,
        D_mul := D_mul, D_cont := D_cont, D_G := D_G, D_K := D_K, compact := compact } =
      { G := G_1, G_zero := G_zero_1, G_add := G_add_1, G_norm := G_norm_1, G_cont := G_cont_1, K := K_1,
        K_symm := K_symm_1, CK := CK_1, K_bound := K_bound_1, K_cont := K_cont_1, K_shift := K_shift_1, D := D_1,
        D_norm := D_norm_1, D_one := D_one_1, D_mul := D_mul_1, D_cont := D_cont_1, D_G := D_G_1, D_K := D_K_1,
        compact := compact_1 } →
    G = G_1 ∧ K = K_1 ∧ CK = CK_1 ∧ D = D_1

∀ {α ν : ℝ} {u₀ : Breakdown.Space → Breakdown.Space} {u : ℝ → Breakdown.Space → Breakdown.Space}
  {p : ℝ → Breakdown.Space → ℝ},
  Breakdown.IsFractionalSolution α ν u₀ u p → ∀ t > 0, ∀ (x : Breakdown.Space), Breakdown.divergenceAt (u t) x = 0

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (τ : ℝ) (u v : X),
  F.Ks τ u v = (F.D (Real.exp (-τ))) (((F.K (1 - Real.exp (-τ))) u) v)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  {F : Breakdown.ScaledMildFramework X κ} {ρ : X ≃ₗᵢ[ℝ] X},
  F.Commutes ρ → ∀ (τ : ℝ) (u v : X), ρ (((F.K τ) u) v) = ((F.K τ) (ρ u)) (ρ v)

∀ {X : Type} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  {F : Breakdown.ScaledMildFramework X κ} {ρ : X ≃ₗᵢ[ℝ] X} {w : ℝ → X} {P : ℝ},
  F.IsOrbit ρ w P → Function.Periodic (fun s => ‖w s‖) P

∀ {α ν : ℝ} {u₀ : Breakdown.Space → Breakdown.Space} {u : ℝ → Breakdown.Space → Breakdown.Space}
  {p : ℝ → Breakdown.Space → ℝ},
  Breakdown.IsFractionalSolution α ν u₀ u p → ContDiffOn ℝ (↑⊤) (fun z => p z.1 z.2) (Set.Ici 0 ×ˢ Set.univ)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (self : Breakdown.ScaledMildFramework X κ),
  ∃ S, Dense S ∧ ∀ f ∈ S, ∀ (τ : ℝ), 0 < τ → IsCompactOperator ⇑((self.K τ) f)

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (w : ℝ → X) (s₀ t : ℝ),
  F.selfSimilar w s₀ t = (F.D (1 - t)⁻¹) (w (s₀ - Real.log (1 - t)))

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  (F : Breakdown.ScaledMildFramework X κ) (u : ℝ → X) (a b : ℝ),
  F.IsMildOnIcc u a b ↔ F.toHeatBilinear.IsMildOnIcc u a b

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] [inst_2 : CompleteSpace X] {κ : ℝ}
  {F : Breakdown.ScaledMildFramework X κ} {ρ : X ≃ₗᵢ[ℝ] X},
  F.Commutes ρ → ∀ (t : ℝ) (x : X), ρ ((F.G t) x) = (F.G t) (ρ x)
